What is the output of the following program:
#include <iostream>
using namespace std;
class TestClass
{
public:
     TestClass(int x)
     { cout << x << endl; }
     TestClass()
     { cout << "Hello!" << endl; }
};
int main()
{
     TestClass test;
     return 0;
}

What is the output of the following program:
#include <iostream>
using namespace std;
class TestClass
{
public:
     TestClass(int x)
     { cout << x << endl; }
     TestClass()
     { cout << "Hello!" << endl; }
};
int main()
{
     TestClass test(77);
     return 0;
}

What is the output of the following program:
#include <iostream>
using namespace std;
class TestClass
{
private:
     int val;
     void showVal()
     { cout << val << endl; }
public:
     TestClass(int x)
     { val = x; }
};
int main()
{
     TestClass test(77);
     test.showVal();
     return 0;
}

In the following code, which statement is the throw point?
double divide(int numer, int denom)
{
if (denom == 0)
   throw "ERROR: Cannot divide by zero.\n";
else
   return static_cast<double>(numer)/denom;
}

